    if len(input_data) < 2:
        print("Not enough input provided.")
    else:
        try:
            num1_str = input_data[0]
            num2_str = input_data[1]
            result = multiply_numbers(num1_str, num2_str)
            print(result)
        except IndexError:
            print("Error: Insufficient data for multiplication.")

